package net.civeira.phylax.features.access.tenantconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class WelcomeEmailTemplateVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property welcome email template of tenant config ")
  void test_welcome_email_template_v_o_builder() {
    Assertions.assertFalse(WelcomeEmailTemplateVO.nullValue().getWelcomeEmailTemplate().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(
        WelcomeEmailTemplateVO.tryFrom(null).getWelcomeEmailTemplate().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one",
        WelcomeEmailTemplateVO.from("one").getWelcomeEmailTemplate().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> WelcomeEmailTemplateVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", WelcomeEmailTemplateVO.from("one").toString());
  }
}
